	/*
     * @param	event CreateBankAccountEvent
     */
    @EventHandler( payloadType=CreateBankAccountEvent.class )
    public void handle( CreateBankAccountEvent event) {
	    LOGGER.info("handling CreateBankAccountEvent - " + event );
	    BankAccount entity = new BankAccount();
            entity.setBankAccountId( event.getBankAccountId() );
            entity.setAccountHolder( event.getAccountHolder() );
            entity.setBankName( event.getBankName() );
            entity.setIban( event.getIban() );
            entity.setBic( event.getBic() );
            entity.setAccountNumber( event.getAccountNumber() );
            entity.setRoutingNumber( event.getRoutingNumber() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBankAccount( entity );
    }

    /*
     * @param	event UpdateBankAccountEvent
     */
    @EventHandler( payloadType=UpdateBankAccountEvent.class )
    public void handle( UpdateBankAccountEvent event) {
    	LOGGER.info("handling UpdateBankAccountEvent - " + event );
    	
	    BankAccount entity = new BankAccount();
            entity.setBankAccountId( event.getBankAccountId() );
            entity.setAccountHolder( event.getAccountHolder() );
            entity.setBankName( event.getBankName() );
            entity.setIban( event.getIban() );
            entity.setBic( event.getBic() );
            entity.setAccountNumber( event.getAccountNumber() );
            entity.setRoutingNumber( event.getRoutingNumber() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindBankAccount( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBankAccount( entity );        
    }
    
