/**
 * emit to subscription queries of type FindBankAccount,
 * but only if the id matches
 *
 * @param		entity	BankAccount
 */
	protected void emitFindBankAccount( BankAccount entity ) {
		LOGGER.info("handling emitFindBankAccount" );
		
	    queryUpdateEmitter.emit(FindBankAccountQuery.class,
	                            query -> query.getFilter().getBankAccountId().equals(entity.getBankAccountId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBankAccount
	 * 
	 * @param		entity	BankAccount
	 */
	protected void emitFindAllBankAccount( BankAccount entity ) {
		LOGGER.info("handling emitFindAllBankAccount" );
		
	    queryUpdateEmitter.emit(FindAllBankAccountQuery.class,
	                            query -> true,
	                            entity);
	}

